// Valida y normaliza la consulta que manda la landing.
// Contrato (src/sections/Contact.jsx): name, phone, email, service, message,
// consent, origen, enviado. El honeypot ya se descarta en el navegador.
const b = $input.first().json.body || {};

const SERVICIOS = {
  despido: 'Despido injustificado o trabajo no registrado',
  art: 'Accidente de trabajo o enfermedad profesional (ART)',
  sueldo: 'Diferencias salariales o sueldo mal liquidado',
  veraz: 'Salir de Veraz / Nosis / BCRA',
  otro: 'Familia, Sucesiones o Transito',
};
const ALTA = ['despido', 'art'];

const linea = (v, max) => String(v ?? '').replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
const texto = (v, max) => String(v ?? '').replace(/[\u0000-\u0009\u000b-\u001f\u007f]/g, ' ').replace(/\n{3,}/g, '\n\n').trim().slice(0, max);
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const nombre = linea(b.name, 120);
const telefono = linea(b.phone, 40);
const email = linea(b.email, 160);
const servicio = linea(b.service, 20);
const mensaje = texto(b.message, 3000);
const digitos = telefono.replace(/\D/g, '');

const errores = [];
if (b.consent !== true) errores.push('consentimiento');
if (nombre.length < 2) errores.push('nombre');
if (digitos.length < 8 || digitos.length > 15 || !/^[0-9+()\-.\s]+$/.test(telefono)) errores.push('telefono');
if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) errores.push('email');
if (!SERVICIOS[servicio]) errores.push('motivo');
if (mensaje.length < 5) errores.push('mensaje');

if (errores.length) {
  return [{ json: { ok: false, errores } }];
}

// Link de WhatsApp solo si el numero se normaliza sin ambiguedad.
let wa = null;
let d = digitos;
if (d.startsWith('549') && d.length === 13) wa = d;
else if (d.startsWith('54') && d.length === 12) wa = '549' + d.slice(2);
else if (d.length === 10) wa = '549' + d;
const waLink = wa ? `https://wa.me/${wa}` : '';

const fecha = $now.setZone('America/Argentina/Buenos_Aires').toFormat('dd/MM/yyyy HH:mm');
const prioridad = ALTA.includes(servicio) ? 'Alta' : 'Normal';
const motivo = SERVICIOS[servicio];

const fila = (k, v) => `<tr><td style="padding:4px 12px 4px 0;color:#555"><b>${k}</b></td><td style="padding:4px 0">${v}</td></tr>`;
const html = `
<h3 style="margin:0 0 8px">Nueva consulta desde la web</h3>
<table style="font-family:Arial,sans-serif;font-size:14px">
${fila('Fecha', esc(fecha))}
${fila('Prioridad', esc(prioridad))}
${fila('Nombre', esc(nombre))}
${fila('Telefono', esc(telefono))}
${fila('Email', email ? esc(email) : '(no informado)')}
${fila('Motivo', esc(motivo))}
</table>
<p style="font-family:Arial,sans-serif;font-size:14px"><b>Situacion:</b><br>${esc(mensaje).replace(/\n/g, '<br>')}</p>
${waLink ? `<p><a href="${waLink}">Responder por WhatsApp</a></p>` : ''}
<p style="font-family:Arial,sans-serif;font-size:12px;color:#777">Datos sujetos a secreto profesional y Ley 25.326. Origen: landing.</p>`;

return [{ json: { ok: true, fecha, prioridad, nombre, telefono, email, motivo, mensaje, waLink, html,
  asunto: `[Web] ${prioridad === 'Alta' ? 'URGENTE - ' : ''}${motivo} - ${nombre}` } }];
